MATCH (a:PlantItem {tag: 'EA-3101'}), (b:PlantItem {tag: 'P-3101'})
WHERE EXISTS {
  MATCH (a) ((:PlantItem WHERE tag <> 'V-3101')-[:line_to]->(:PlantItem WHERE tag <> 'V-3101'))+ (b)
}
RETURN a.tag AS from_tag, b.tag AS to_tag

MATCH (:PlantItem {tag: 'D-5501'})-[:is_drawn_on]->(s:Sheet)
