MATCH (a:PlantItem {tag: 'P-4901'}), (b:PlantItem {tag: 'V-5001'})
RETURN a.tag AS from_tag, b.tag AS to_tag,
       EXISTS { (a)-[:line_to*1..]->(b) } AS reachable;

MATCH (a:PlantItem {tag: 'E-5503'}), (b:PlantItem {tag: 'E-5501'})
RETURN b.tag AS tag,
       EXISTS {
         MATCH p = shortestPath((a)-[:line_to*1..]->(b))
         WHERE NONE(n IN nodes(p) WHERE n.tag = 'T-5501')
       } AS can_flow_without_T_5501

MATCH (a:PlantItem {tag: 'F-2501'}), (b:PlantItem {tag: 'V-2701'}), (v:Valve)
WHERE v <> a AND v <> b
  AND EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (a:PlantItem {tag: 'F-3201'}), (b:PlantItem {tag: 'P-3403'})
RETURN EXISTS {
  MATCH p = (a)-[:line_to*1..]->(b)
  WHERE none(n IN nodes(p) WHERE n.tag = 'TV-31001')
} AS reachable, a.tag AS from_tag, b.tag AS to_tag

