MATCH (source:PlantItem {tag: 'F-2501'}), (v:Valve)
WHERE EXISTS { (source)-[:line_to*1..]->(v) }
  AND NOT EXISTS {
    MATCH (u:Valve)
    WHERE u <> v
      AND EXISTS { (source)-[:line_to*1..]->(u) }
      AND EXISTS { (u)-[:line_to*1..]->(v) }
  }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (p:PlantItem {tag: 'P-4101'}), (v:Valve)
