MATCH (v:ButterflyValve:Valve {line_number: '6-P-230005-B1A-N'})-[:line_to*1..]->(:PlantItem {tag: 'YV-24001'})
RETURN DISTINCT v.tag AS tag, coalesce(v.operating_position, 'NO') AS normal_position
